SELECT
  b.domain AS domain,
      b.as_of AS compiled_at,
      b.first_seen AS ctl_first_seen_at,
      b.as_of AS ctl_last_seen_at,
      b.last_verified_at AS http_first_seen_at,
      b.last_verified_at AS http_last_seen_at,
      b.as_of AS http_last_checked_at,
      b.business_model AS estimated_business_model,
      b.classification_confidence AS estimated_business_model_confidence,
      b.classification_source AS estimated_business_model_evidence,
      b.industry AS estimated_industry,
      b.classification_confidence AS estimated_industry_confidence,
      b.estimated_revenue AS estimated_revenue,
      b.revenue_confidence AS estimated_revenue_confidence,
      b.revenue_evidence AS estimated_revenue_evidence,
      b.estimated_employees AS estimated_employees,
      b.revenue_confidence AS estimated_employees_confidence,
      b.revenue_evidence AS estimated_employees_evidence,
      b.inferred_country AS estimated_country,
      if(b.http_country_evidence != '', concat(b.http_country_evidence_src, ':', b.http_country_evidence), if(b.rdap_registrant_country != '', concat('rdap:', b.rdap_registrant_country), concat('tld:', b.ctl_tld, ';lang:', b.http_language, ';asn:', b.bgp_asn_country))) AS estimated_country_evidence,
      multiIf(b.http_country_evidence != '', 0.95, b.rdap_registrant_country != '', 0.85, b.inferred_country != '', 0.6, NULL) AS estimated_country_confidence,
      b.hq_location AS estimated_hq_location,
      if(b.hq_location != '', 'about page', '') AS estimated_hq_location_evidence,
      if(b.mission_summary != '', b.mission_summary, b.mission) AS estimated_summary,
      multiIf(b.mission_summary != '', 'registry', b.mission != '', 'about page', '') AS estimated_summary_evidence,
      b.is_junk AS estimated_junk,
      if(b.depth_enriched_at IS NOT NULL, b.depth_enriched_at, b.as_of) AS estimated_at,
      b.pipeline_version AS estimated_version,
      arrayDistinct(arrayFilter(x -> x != '' AND has(_catalog, x), arrayMap(x -> transform(x, _alias_from, _alias_to, x), arrayConcat(splitByChar('|', b.http_tech), splitByChar('|', b.http_apps))))) AS http_tech,
