      arrayFilter(x -> x != '', splitByChar('|', b.job_locations)) AS hr_locations,
      if(b.job_count IS NOT NULL, b.depth_enriched_at, NULL) AS hr_last_seen_at,
      arrayExists(x -> x IN ('careers', 'jobs', 'career', 'hiring', 'recruiting', 'talent', 'join', 'apply'), splitByChar('|', b.ctl_subdomains)) AS ctl_has_hiring_subdomain,
      b.product_count AS shop_product_count,
      b.new_products_30d AS shop_new_products_30d,
      b.last_product_at AS shop_last_product_at,
      b.price_min AS shop_price_min,
      b.price_avg AS shop_price_avg,
      b.price_max AS shop_price_max,
      b.oos_ratio AS shop_oos_ratio,
      b.discount_depth AS shop_discount_depth,
      b.vendor_count AS shop_vendor_count,
      b.catalog_age_days AS shop_catalog_age_days,
      arrayFilter(x -> x != '', splitByChar('|', b.product_types)) AS shop_product_types,
      b.shop_theme AS shop_theme,
      b.shop_theme_store_id AS shop_theme_store_id,
      b.shop_currency AS shop_currency,
      b.shop_locales AS shop_locales,
      b.shopify_plus AS shop_plus,
