      '' AS verified_industry,
      NULL AS verified_founded_year,
      NULL AS verified_at,
      arrayFilter(x -> x != '', splitByChar('|', b.dns_a)) AS dns_a,
      arrayFilter(x -> x != '', splitByChar('|', b.dns_mx)) AS dns_mx,
      b.dns_dmarc AS dns_dmarc,
      b.dns_bimi AS dns_bimi,
      b.dns_dkim AS dns_dkim,
      if(b.dns_alive = 1, b.as_of, NULL) AS dns_last_seen_at,
      b.ctl_tld AS ctl_tld,
      b.ctl_issuer AS ctl_issuer,
      b.ctl_subdomain_count AS ctl_subdomain_count,
      arrayFilter(x -> x != '', splitByChar('|', b.ctl_subdomains)) AS ctl_subdomains,
      b.rdap_domain_created_at AS rdap_created_at,
      b.rdap_domain_expires_at AS rdap_expires_at,
      b.rdap_domain_updated_at AS rdap_updated_at,
      b.rdap_registrar AS rdap_registrar,
      arrayFilter(x -> x != '', splitByChar('|', b.rdap_nameservers)) AS rdap_nameservers,
      arrayFilter(x -> x != '', splitByChar('|', b.rdap_status)) AS rdap_status,
      b.rdap_registrant_country AS rdap_registrant_country,
      if(b.rdap_registrar != '', b.as_of, NULL) AS rdap_last_seen_at,
      b.bgp_asn_number AS bgp_asn,
      b.bgp_asn_org AS bgp_asn_org,
      b.bgp_asn_country AS bgp_country,
      if(b.bgp_asn_number != '', b.as_of, NULL) AS bgp_last_seen_at,
      b.tranco_rank AS tranco_rank,
      b.majestic_rank AS majestic_rank,
      b.majestic_ref_subnets AS majestic_ref_subnets,
      b.news_count AS news_count,
      b.last_funding_usd AS news_last_funding_usd,
      NULL AS news_last_seen_at
FROM businesses AS b
SETTINGS max_threads = 2, max_insert_threads = 2, max_memory_usage = 3000000000;

